// Keep ONLY example.com placeholders committed to the repo — paste real URLs locally.
const rawUrls = [
  'https://example.com/competitor-1',
  'https://example.com/competitor-2',
  'https://example.com/competitor-3'
];

const now = new Date().toISOString();
function pad(n){ return String(n).padStart(2, '0'); }
const d = new Date();
const run_id = 'firecrawl_' + d.getFullYear() + pad(d.getMonth()+1) + pad(d.getDate()) + '_' + pad(d.getHours()) + pad(d.getMinutes()) + pad(d.getSeconds());

const cleaned = [];
for (let u of rawUrls) {
  if (u == null) continue;
  u = String(u).trim();
  if (u === '') continue;
  cleaned.push(u);
}
const capped = cleaned.slice(0, 5); // HARD CAP: max 5 URLs

const items = [];
let idx = 0;
for (const u of capped) {
  idx++;
  items.push({ json: {
    target_url: u,
    source_type: 'scraped_web',
    platform: 'website',
    parsed_at: now,
    source_note: 'firecrawl_url_list_manual',
    run_id: run_id,
    batch_index: idx,
    force_reprocess: false
  }});
}
return items;

const j = $json;
let u = String(j.target_url || '').trim();
let normalized = u;
try {
  if (u) {
    const noFrag = u.split('#')[0];
    const url = new URL(noFrag);
    url.protocol = (url.protocol || '').toLowerCase();
    url.hostname = (url.hostname || '').toLowerCase();
    const drop = ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','gclid','yclid','fbclid'];
    for (const p of drop) url.searchParams.delete(p);
    let path = url.pathname || '/';
    if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);
    url.pathname = path;
    normalized = url.toString();
  }
} catch(e) {
  normalized = u;
}
return [{ json: {
  target_url: u || normalized,
  normalized_source_url: normalized,
  source_url: normalized,
  source_type: j.source_type || 'scraped_web',
  platform: j.platform || 'website',
