  onlyMainContent: true,
  onlyCleanContent: false,
  removeBase64Images: true,
  blockAds: true,
  timeout: 60000,
  storeInCache: true
}}];

const resp = $json;
const ctx = $('Evaluate Dedup').first().json;
const targetUrl = ctx.target_url || ctx.source_url || '';
const sourceUrlBase = ctx.source_url || targetUrl;
const run_id = ctx.run_id || '';
const batch_index = ctx.batch_index || 0;
const parsedAt = ctx.parsed_at || new Date().toISOString();
const now = new Date().toISOString();
function cap(s, n) { return (s == null ? '' : String(s)).substring(0, n); }

function technicalErrorRow(errSummary, preview) {
  return [{ json: {
    created_at: now, source_type: 'scraped_web', platform: 'website', source_url: sourceUrlBase, parsed_at: parsedAt,
    published_at: '', freshness_status: 'unknown', entity_type: 'irrelevant', company_name: '', profile_name: '',
    profile_url: '', region: '', service_type: 'unknown', offer_text: '', terms: '', contact_public: '',
    text_context: '', detected_need: '', competitor_strength: 1, lead_signal_score: 1, content_idea_score: 1,
