    processing_status: 'technical_error', parse_method: 'firecrawl_error',
    parse_error: cap('Firecrawl scrape failed: ' + errSummary, 800),
    raw_response_preview: cap(preview, 500), route: 'technical_errors', needs_manual_review: true,
    repair_used: false, repair_status: '', run_id: run_id, batch_index: batch_index
  }}];
}

const apiError = (resp == null) || resp.error || resp.success === false || (resp.code && resp.code >= 400) || (resp.statusCode && resp.statusCode >= 400);
if (apiError) {
  const summary = cap(JSON.stringify((resp && (resp.error || resp.message || resp.code || resp.statusCode)) || 'unknown error'), 300);
  return technicalErrorRow(summary, cap(JSON.stringify(resp), 500));
}

const data = resp.data || resp;
let markdown = (resp.data && resp.data.markdown) || resp.markdown || (data && data.markdown) || (resp.data && resp.data.data && resp.data.data.markdown) || '';
const metadata = (resp.data && resp.data.metadata) || resp.metadata || (data && data.metadata) || {};
markdown = String(markdown).replace(/\r/g, '');

// Clean: drop image lines and inline image/svg data fragments
const cleanedLines = [];
for (const line of markdown.split('\n')) {
  const t = line.trim();
  if (t.startsWith('![')) continue;
  if (/data:image\/svg\+xml/i.test(line)) continue;
  if (/data:image\/[a-z]+;base64/i.test(line)) continue;
  cleanedLines.push(line);
}
let cleaned = cleanedLines.join('\n').replace(/\n{3,}/g, '\n\n').trim();

const meaningful = cleaned.replace(/[#>*_|]/g, '').replace(/\s+/g, ' ').trim();
if (!cleaned || meaningful.length < 80) {
  return technicalErrorRow('scrape succeeded but markdown empty/unusable (' + meaningful.length + ' meaningful chars)', cap(cleaned || JSON.stringify(metadata), 500));
}

// Commercially relevant lines first (stable order within groups), then cap at 3500
const relevantTerms = ['кредит','займ','залог','птс','авто','автомобил','недвиж','квартир','дом','земл','рефинанс','ипотек','ставка','сумма','одобрен','плохая кредитн','просроч','телефон','москва','руб','%'];
const relevant = [];
const rest = [];
for (const line of cleaned.split('\n')) {
  const low = line.toLowerCase();
  if (relevantTerms.some(t => low.includes(t))) relevant.push(line); else rest.push(line);
}
let prioritized = (relevant.length > 0) ? (relevant.join('\n') + '\n' + rest.join('\n')).replace(/\n{3,}/g, '\n\n').trim() : cleaned;

const sourceUrl = metadata.sourceURL || metadata.url || sourceUrlBase;
const title = metadata.title || '';
const description = metadata.description || '';

return [{ json: {
  route: '', source_type: 'scraped_web', platform: 'website', source_url: sourceUrl, profile_url: '',
  published_at: '', parsed_at: parsedAt, text_context: cap(prioritized, 3500),
  page_title: cap(title, 300), page_description: cap(description, 500),
  run_id: run_id, batch_index: batch_index
}}];

const response = $json;
const srcRecord = $('Normalize Firecrawl Output').first().json;
function cap(s, n) { return (s == null ? '' : String(s)).substring(0, n); }
function extractBalanced(s) {
  const start = s.indexOf('{');
  if (start === -1) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < s.length; i++) {
    const c = s[i];
    if (inStr) { if (esc) { esc = false; } else if (c === '\\') { esc = true; } else if (c === '"') { inStr = false; } continue; }
    if (c === '"') { inStr = true; continue; }
    if (c === '{') depth++;
    else if (c === '}') { depth--; if (depth === 0) return s.substring(start, i + 1); }
  }
  return null;
}
function tryParse(text) {
  let txt = String(text).trim();
  txt = txt.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  txt = txt.replace(/^```\s*/, '').replace(/```\s*$/, '').trim();
  const norm = (x) => x.replace(/[‘’]/g, "'").replace(/[“”«»]/g, '"');
  try { return { ok: true, obj: JSON.parse(norm(txt)), candidate: cap(txt, 500) }; } catch(e) {}
  const bal = extractBalanced(txt);
  if (bal) { try { return { ok: true, obj: JSON.parse(norm(bal)), candidate: cap(bal, 500) }; } catch(e) {} }
  const s = txt.indexOf('{'), e2 = txt.lastIndexOf('}');
  if (s !== -1 && e2 !== -1 && e2 > s) { const slice = txt.substring(s, e2 + 1); try { return { ok: true, obj: JSON.parse(norm(slice)), candidate: cap(slice, 500) }; } catch(e) {} return { ok: false, candidate: cap(slice, 500) }; }
  return { ok: false, candidate: cap(txt, 500) };
}
function fail(err, prev, summary) {
  return [{ json: {
    parse_ok: false, parse_method: 'primary_json', repair_used: false,
    processing_status: 'technical_error_candidate',
    primary_parse_error: cap(err, 300),
    primary_raw_response_preview: cap(prev, 500),
    extracted_candidate_preview: cap(prev, 500),
    content_summary: summary,
    parse_error: cap(err, 300),
    raw_response_preview: cap(prev, 500),
    original_record: srcRecord
  }}];
}

if (response.error || response.status >= 400) {
  const prev = cap(JSON.stringify(response), 500);
  return fail('Primary HTTP error: ' + cap(JSON.stringify(response.error || response.status), 300), prev, 'http_error');
}

let textItem, contentSummary = '';
try {
  if (!response.content || !Array.isArray(response.content)) throw new Error('no content array');
  contentSummary = response.content.map(c => c.type).join(',');
  textItem = response.content.find(c => c.type === 'text');
} catch(e) {
  return fail('Primary parse failed: no content array: ' + e.message, cap(JSON.stringify(response), 500), 'no_content_array');
}
if (!textItem || !textItem.text) {
  return fail('Primary parse failed: no text item', cap(JSON.stringify(response.content || response), 500), contentSummary || 'no_text_item');
}

const rawPreview = cap(textItem.text, 500);
const res = tryParse(textItem.text);
if (!res.ok) {
  const out = fail('Primary JSON parse failed', rawPreview, 'text_present_json_invalid');
  out[0].json.extracted_candidate_preview = cap(res.candidate || '', 500);
  return out;
}

return [{ json: {
  parse_ok: true,
  parse_method: 'primary_json',
  repair_used: false,
  repair_status: '',
  parse_error: '',
  raw_response_preview: rawPreview,
  ...res.obj
}}];

const input = $json;
const srcRecord = $('Normalize Firecrawl Output').first().json;
function cap(s, n) { return (s == null ? '' : String(s)).substring(0, n); }

const rawPreview = cap(input.primary_raw_response_preview || input.raw_response_preview || 'empty', 500);
const primaryErr = cap(input.primary_parse_error || input.parse_error || 'Primary parse failed', 300);

const repairSystem = `You are a JSON repair formatter, not a market analyst. Convert the raw response into strict JSON. Do not invent facts. If raw response is unusable, return an object that can be routed to technical_errors.
Return ONLY a valid JSON object. Do not say Repairing. Do not explain. Do not use markdown.
Return JSON only. No markdown. First char {, last char }.
Fields: created_at, source_type, platform, source_url, parsed_at, published_at, freshness_status, entity_type, company_name, profile_name, profile_url, region, service_type, offer_text, terms, contact_public, text_context, detected_need, competitor_strength, lead_signal_score, content_idea_score, quality_score, reason, recommended_action, status.
Unknown text -> "". Unknown score -> 1. Unusable -> status=skipped, entity_type=irrelevant, recommended_action=ignore, all scores=1.
Enums: entity_type[competitor,lead_signal,market_signal,content_idea,irrelevant]; recommended_action[monitor,contact,create_content,ignore,investigate]; status[analyzed,skipped]; freshness_status[fresh,recent,old,unknown].`;

const userMsg = JSON.stringify({
  original_record: {
    source_type: srcRecord.source_type || '',
    platform: srcRecord.platform || '',
    source_url: srcRecord.source_url || '',
    profile_url: srcRecord.profile_url || '',
    parsed_at: srcRecord.parsed_at || '',
    published_at: srcRecord.published_at || '',
    text_context: cap(srcRecord.text_context || '', 500)
  },
  raw_primary_response: rawPreview,
  primary_parse_error: primaryErr
});

return [{ json: {
  model: 'claude-sonnet-4-6',
  max_tokens: 700,
  temperature: 0,
  system: repairSystem,
  messages: [{ role: 'user', content: userMsg }]
}}];

const response = $json;
const primary = $('Parse Primary JSON').first().json;
const src = $('Normalize Firecrawl Output').first().json;
function cap(s, n) { return (s == null ? '' : String(s)).substring(0, n); }
function extractBalanced(s) {
  const start = s.indexOf('{');
  if (start === -1) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < s.length; i++) {
    const c = s[i];
    if (inStr) { if (esc) { esc = false; } else if (c === '\\') { esc = true; } else if (c === '"') { inStr = false; } continue; }
    if (c === '"') { inStr = true; continue; }
    if (c === '{') depth++;
    else if (c === '}') { depth--; if (depth === 0) return s.substring(start, i + 1); }
  }
  return null;
}
function tryParse(text) {
  let txt = String(text).trim();
  txt = txt.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  txt = txt.replace(/^```\s*/, '').replace(/```\s*$/, '').trim();
  const norm = (x) => x.replace(/[‘’]/g, "'").replace(/[“”«»]/g, '"');
  try { return { ok: true, obj: JSON.parse(norm(txt)) }; } catch(e) {}
  const bal = extractBalanced(txt);
  if (bal) { try { return { ok: true, obj: JSON.parse(norm(bal)) }; } catch(e) {} }
  const s = txt.indexOf('{'), e2 = txt.lastIndexOf('}');
  if (s !== -1 && e2 !== -1 && e2 > s) { try { return { ok: true, obj: JSON.parse(norm(txt.substring(s, e2 + 1))) }; } catch(e) {} }
  return { ok: false };
}

const primaryErr = cap(primary.primary_parse_error || primary.parse_error || 'unknown', 300);
const primaryPreview = cap(primary.primary_raw_response_preview || primary.raw_response_preview || '', 500);
const now = new Date().toISOString();
const run_id = src.run_id || '';
const batch_index = src.batch_index || 0;
const parsedAt = src.parsed_at || now;

// Deterministic competitor fallback after primary + repair failure (DEC-052).
function fallback(repairErr) {
  const combinedErr = cap('Primary: ' + primaryErr + ' | Repair: ' + repairErr, 800);
  const textCtx = String(src.text_context || '');
  const rawAll = (textCtx + ' ' + primaryPreview).toLowerCase();
  const signals = ['кредит','займ','залог','птс','авто','автомобил','недвиж','квартир','дом','земл','рефинанс','ипотек','ставка','сумма','одобрен','плохая кредитн','просроч','телефон','москва','руб','%'];
  let count = 0;
  for (const t of signals) { if (rawAll.includes(t)) count++; }

  if (count < 5) {
    let preview = primaryPreview;
    if (preview.length < 440) preview = cap(preview + ' || REPAIR_ERR: ' + repairErr, 500);
    return [{ json: {
      parse_ok: false, parse_method: 'technical_error', repair_used: true, repair_status: 'failed',
      processing_status: 'technical_error', route: 'technical_errors', needs_manual_review: true,
      parse_error: combinedErr, raw_response_preview: cap(preview, 500),
      original_record: primary.original_record || {}, run_id: run_id, batch_index: batch_index
    }}];
  }

  const low = textCtx.toLowerCase();
  let company = 'Конкурент без бренда';
  if (low.includes('мосинвестфинанс') || low.includes('mosinvest')) company = 'МосИнвестФинанс';
  else if (low.includes('lioncredit') || low.includes('lion credit')) company = 'LionCredit';
  else { try { const h = new URL(src.source_url || '').hostname.replace(/^www\./, ''); if (h) company = h; } catch(e) {} }

  const hasAuto = low.includes('птс') || low.includes('pts') || low.includes('авто') || low.includes('автомобил') || low.includes('машин');
  const hasRealEstate = low.includes('недвиж') || low.includes('квартир') || low.includes('дом') || low.includes('земл');
  let service = 'generic_lending';
  if (hasAuto && !hasRealEstate) service = 'pts_loan';
  else if (hasRealEstate && !hasAuto) service = 'secured_real_estate_loan';

  let offer = '';
  for (const line of textCtx.split('\n')) { const l = line.trim().toLowerCase(); if ((l.includes('кредит') || l.includes('займ') || l.includes('залог')) && line.trim().length > 10) { offer = line.trim(); break; } }
  offer = cap(offer, 220);

  let terms = '';
  for (const line of textCtx.split('\n')) { const l = line.toLowerCase(); if (l.includes('%') || l.includes('ставк') || l.includes('сумма') || l.includes('руб')) { terms += (terms ? ' ' : '') + line.trim(); if (terms.length >= 200) break; } }
  terms = cap(terms, 220);

  const region = (low.includes('москва') || low.includes('московск')) ? 'Москва' : '';
  const hasContactOrAmount = low.includes('телефон') || /\+?\d[\d\s().-]{7,}/.test(textCtx) || low.includes('руб') || low.includes('%');
  const strength = (count >= 8 && hasContactOrAmount) ? 80 : 70;

  return [{ json: {
    created_at: now, source_type: 'scraped_web', platform: 'website', source_url: src.source_url || '', parsed_at: parsedAt,
    published_at: '', freshness_status: 'unknown', entity_type: 'competitor', company_name: company,
    profile_name: '', profile_url: '', region: region, service_type: service,
    offer_text: offer, terms: terms, contact_public: '', text_context: cap(textCtx, 3500), detected_need: '',
    competitor_strength: strength, lead_signal_score: 1, content_idea_score: 1, quality_score: strength,
    reason: 'Claude вернул невалидный JSON, но страница содержит явные признаки конкурента в нише залогового кредитования: продукты, условия, суммы/ставки или контакт. Запись отправлена в мониторинг, чтобы не терять полезный источник.',
    recommended_action: 'monitor', status: 'analyzed', processing_status: 'parsed_success',
    parse_method: 'deterministic_competitor_fallback', parse_error: combinedErr,
    raw_response_preview: cap(primaryPreview, 500), route: 'monitor_queue', needs_manual_review: true,
    repair_used: true, repair_status: 'failed_fallback', run_id: run_id, batch_index: batch_index
  }}];
}

if (response.error || response.status >= 400) {
  return fallback('Repair HTTP error: ' + cap(JSON.stringify(response.error || response.status), 300));
}

let textItem;
try { textItem = (response.content || []).find(c => c.type === 'text'); } catch(e) { textItem = null; }
if (!textItem || !textItem.text) {
  return fallback('No text item in repair response');
}

const res = tryParse(textItem.text);
if (!res.ok) {
  return fallback('Repair JSON parse failed');
}

return [{ json: {
  parse_ok: true,
  parse_method: 'repaired_json',
  repair_used: true,
  repair_status: 'success',
  parse_error: '',
  raw_response_preview: cap(textItem.text, 500),
  ...res.obj
}}];

const data = $json;
const srcRecord = $('Normalize Firecrawl Output').first().json;

function clamp(v) { const n = parseInt(v); return isNaN(n) ? 1 : Math.min(100, Math.max(1, n)); }
function truncate(s, n) { return (s == null ? '' : String(s)).substring(0, n); }

// Normalize free-text service_type into allowed enum values
function normalizeServiceType(raw, hay) {
  const allowed = ['secured_auto_loan','secured_real_estate_loan','pts_loan','refinancing','mortgage_adjacent','generic_lending'];
  const r = (raw || '').toLowerCase().trim();
  if (allowed.includes(r)) return r;
  const s = r + ' ' + (hay || '');
  if (s.includes('птс') || s.includes('pts')) return 'pts_loan';
  if ((s.includes('авто') || s.includes('машин')) && (s.includes('залог') || s.includes('collateral') || s.includes('ломбард'))) return 'secured_auto_loan';
  if (s.includes('недвиж') || s.includes('квартир') || s.includes('дом') || s.includes('земл')) return 'secured_real_estate_loan';
  if (s.includes('рефинанс') || s.includes('refinanc')) return 'refinancing';
  if (s.includes('ипотек') || s.includes('mortgage')) return 'mortgage_adjacent';
  if (s.includes('бизнес') || s.includes('business')) {
    if (s.includes('недвиж') || s.includes('квартир')) return 'secured_real_estate_loan';
    return 'generic_lending';
  }
  return 'unknown';
}

// Descriptive company_name fallback for competitors (never invent a brand)
function companyNameFallback(existing, entity, hay) {
  if (existing && String(existing).trim() !== '') return existing;
  if (entity === 'competitor' && (hay.includes('мфо') || hay.includes('микрофинанс') || hay.includes('mfo'))) return 'МФО / частный кредитор';
  if (hay.includes('частный инвестор')) return 'Частный инвестор';
  if (hay.includes('автоломбард')) return 'Автоломбард';
  if (hay.includes('брокер')) return 'Брокер';
  if (entity === 'competitor') return 'Конкурент без бренда';
  return '';
}

// recommended_action normalization driven by final route
function normalizeAction(route, entity, action, leadScore) {
  if (route === 'technical_errors') return 'ignore';
  if (route === 'skipped_log') return 'ignore';
  if (route === 'results' && entity === 'lead_signal') return 'contact';
  if (route === 'review_queue') {
    if (entity === 'lead_signal' && action === 'contact' && leadScore >= 70) return 'contact';
    return 'investigate';
  }
  if (route === 'monitor_queue' && entity === 'competitor') return 'monitor';
  if (route === 'content_queue') {
    if (action === 'contact' || action === 'investigate') return action;
    return 'create_content';
  }
  return action;
}

// Pass-through for confirmed technical_error (from Parse Repaired JSON)
